import { getPassiveBonuses } from "./passiveBonuses.js";
import { resolveDerivedStats } from "./derivedStats.js";

/**
 * Merge all stat inputs into a canonical stat view for combat/damage consumers.
 * Derived-expression stats are authoritative semantic channels; passive/equipment
 * bonuses are treated as additional input sources to those channels.
 *
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} entityId
 */
export function resolveCanonicalStats(world, entityId) {
  const id = Number(entityId || 0) | 0;
  const resolved = resolveDerivedStats(world, id);
  const passive = getPassiveBonuses(world, id);

  const baseDexterity = Number(resolved?.dexterity || 0);
  const dexterityDerived = Number(passive?.dexterityDerived || 0);
  const totalDexterity = baseDexterity + dexterityDerived;
  const baseDexBonus = Math.floor(Math.max(0, baseDexterity - 10) / 2);
  const totalDexBonus = Math.floor(Math.max(0, totalDexterity - 10) / 2);
  const dexBonusDelta = totalDexBonus - baseDexBonus;

  const accuracyDerived = Number(passive?.accuracyDerived || 0);
  const damagePowerDerived = Number(passive?.damagePowerDerived || 0);
  const physicalPenetrationDerived = Number(passive?.physicalPenetrationDerived || 0);
  const bluntPenetrationDerived = Number(passive?.bluntPenetrationDerived || 0);
  const slashPenetrationDerived = Number(passive?.slashPenetrationDerived || 0);
  const piercePenetrationDerived = Number(passive?.piercePenetrationDerived || 0);
  const evadeDerived = Number(passive?.evadeDerived || 0);
  const mitigationDerived = Number(passive?.mitigationDerived || 0);
  const critChanceDerived = Number(passive?.critChanceDerived || 0);
  const critMultDerived = Number(passive?.critMultDerived || 0);

  return Object.freeze({
    ...resolved,
    dexterity: totalDexterity,
    accuracy: Number(resolved?.accuracy || 0) + accuracyDerived + dexBonusDelta,
    damagePower: Number(resolved?.damagePower || 0) + damagePowerDerived,
    physicalPenetration: Number(resolved?.physicalPenetration || 0) + physicalPenetrationDerived,
    bluntPenetration: Number(resolved?.bluntPenetration || 0) + bluntPenetrationDerived,
    slashPenetration: Number(resolved?.slashPenetration || 0) + slashPenetrationDerived,
    piercePenetration: Number(resolved?.piercePenetration || 0) + piercePenetrationDerived,
    evade: Number(resolved?.evade || 0) + evadeDerived + dexBonusDelta,
    mitigation: Number(resolved?.mitigation || 0) + mitigationDerived,
    critChancePhysical: Number(resolved?.critChancePhysical || 0) + critChanceDerived + (dexBonusDelta * 0.01),
    critChanceSpell: Number(resolved?.critChanceSpell || 0) + critChanceDerived,
    critMultPhysical: Number(resolved?.critMultPhysical || 0) + critMultDerived,
    critMultSpell: Number(resolved?.critMultSpell || 0) + critMultDerived,
    luck: Number(resolved?.luck || 0) + Number(passive?.luckDerived || 0),
    spellHit: Number(resolved?.spellHit || 0) + Number(passive?.spellHitDerived || 0),
    spellAvoid: Number(resolved?.spellAvoid || 0) + Number(passive?.spellAvoidDerived || 0),
    kineticDR: Number(resolved?.kineticDR || 0) + Number(passive?.kineticDRDerived || 0),
    fireResist: Number(resolved?.fireResist || 0) + Number(passive?.fireResistDerived || 0),
    coldResist: Number(resolved?.coldResist || 0) + Number(passive?.coldResistDerived || 0),
    poisonResist: Number(resolved?.poisonResist || 0) + Number(passive?.poisonResistDerived || 0),
    acidResist: Number(resolved?.acidResist || 0) + Number(passive?.acidResistDerived || 0),
    radiationResist: Number(resolved?.radiationResist || 0) + Number(passive?.radiationResistDerived || 0),
    electricOhms: Number(resolved?.electricOhms || 0) + Number(passive?.electricOhmsDerived || 0),
    bluntResist: Number(resolved?.bluntResist || 0) + Number(passive?.bluntResistDerived || 0),
    slashResist: Number(resolved?.slashResist || 0) + Number(passive?.slashResistDerived || 0),
    pierceResist: Number(resolved?.pierceResist || 0) + Number(passive?.pierceResistDerived || 0),
    spellRadius: Number(resolved?.spellRadius || 0) + Number(passive?.spellRadiusDerived || 0),
    visionRange: Number(resolved?.visionRange || 0) + Number(passive?.visionRangeDerived || 0),
    hungerRate: Number(resolved?.hungerRate || 0) + Number(passive?.hungerRateDerived || 0),
    staminaRegen: Number(resolved?.staminaRegen || 0) + Number(passive?.staminaRegenDerived || 0),
    manaRegen: Number(resolved?.manaRegen || 0) + Number(passive?.manaRegenDerived || 0),
  });
}
import { HUNGER_COMBAT_LEVELS } from "../data/hungerCombatLevels.js";
import { resolveResistance } from "./dealDamage.js";
import { resolveCanonicalStats } from "./canonicalStats.js";
import { capabilityStrength, effectStrength, statusStrength } from "./statusFacade.js";
import { getBlindedDefensePenalty, getBlindedAttackPenalty } from "./blindnessExposure.js";
import { COMBAT_POSTURES, CombatPosture } from "../components/CombatPosture.js";
import { Traits } from "../components/Traits.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { getMonster } from "../data/monsters.js";
import { ActiveEffects } from "../components/ActiveEffects.js";
import { AuraStatModifier } from "../components/AuraStatModifier.js";
import { descendantsWith } from "./topology.js";

const MODE_RULES = Object.freeze({
  melee: Object.freeze({
    includeAttackStatuses: true,
    includeDefenseStatuses: true,
    includeStoneskin: true,
    clampAttackAtZero: true,
    clampDefenseAtZero: true,
  }),
  ranged: Object.freeze({
    includeAttackStatuses: false,
    includeDefenseStatuses: false,
    includeStoneskin: true,
    clampAttackAtZero: false,
    clampDefenseAtZero: false,
  }),
});

function shadowVeilAmbushReady(world, entityId) {
  const effects = world.get(entityId, ActiveEffects)?.effects;
  if (!Array.isArray(effects)) return false;
  const veil = effects.find((effect) => effect?.key === "shadow_veil" && (Number(effect.turnsLeft || 0) | 0) > 0);
  return !!veil && veil.meta?.ambushReady !== false;
}

/**
 * @param {string} mode
 */
function getModeRules(mode) {
  const normalized = String(mode || "melee").toLowerCase();
  return MODE_RULES[normalized] || MODE_RULES.melee;
}

/**
 * @param {Array<{stat:'attack'|'defense', source:string, value:number, reason:string}>} modifiers
 * @param {'attack'|'defense'} stat
 * @param {string} source
 * @param {number} value
 * @param {string} reason
 */
function pushModifier(modifiers, stat, source, value, reason) {
  if (!Number.isFinite(value) || value === 0) return;
  modifiers.push({ stat, source, value, reason });
}

/**
 * Resolve deterministic to-hit/defense stats for one combatant.
 * This is the canonical stat pipeline consumed by melee/ranged hit systems.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} entityId
 * @param {{ mode?: 'melee' | 'ranged' | string }} [context]
 */
export function resolveCombatSnapshot(world, entityId, context = {}) {
  const id = Number(entityId || 0) | 0;
  const mode = String(context.mode || "melee").toLowerCase();
  const rules = getModeRules(mode);
  const targetId = Number(context.targetId || 0) | 0;
  const feline = world.get(id, Traits)?.feline === true;
  const targetIdentity = targetId > 0 ? world.get(targetId, NamedIdentity)?.identity : "";
  const targetIsRodent = targetIdentity && getMonster(String(targetIdentity))?.tags?.includes("rodent");
  const felineRodentBonus = feline && targetIsRodent;

  const resolvedStats = resolveCanonicalStats(world, id);

  const accuracy = Number(resolvedStats?.accuracy || 0);
  const damagePower = Number(resolvedStats?.damagePower || 0);
  const physicalPenetration = Number(resolvedStats?.physicalPenetration || 0);
  const bluntPenetration = Number(resolvedStats?.bluntPenetration || 0);
  const slashPenetration = Number(resolvedStats?.slashPenetration || 0);
  const piercePenetration = Number(resolvedStats?.piercePenetration || 0);
  const evade = Number(resolvedStats?.evade || 0);
  const luck = Number(resolvedStats?.luck || 0) + statusStrength(world, id, "lucky");
  const critChance = Number(resolvedStats?.critChancePhysical || 0);
  const critMult = Number(resolvedStats?.critMultPhysical || 0);

  let hunger = 0;
  for (let i = 0; i < HUNGER_COMBAT_LEVELS.length; i++) {
    hunger = Math.max(hunger, statusStrength(world, id, HUNGER_COMBAT_LEVELS[i]));
  }

  const statusTotals = {
    disease: statusStrength(world, id, "disease"),
    hunger,
    weakened: statusStrength(world, id, "weakened"),
    cursed: capabilityStrength(world, id, "cursed"),
    blessed: statusStrength(world, id, "blessed") + (effectStrength(world, id, "divine_shield") > 0 ? 1 : 0),
    stoneskin: statusStrength(world, id, "stoneskin")
      + effectStrength(world, id, "divine_shield")
      + effectStrength(world, id, "iron_flesh")
      + effectStrength(world, id, "barkskin")
      + effectStrength(world, id, "verdant_ward"),
    serpent_hide: statusStrength(world, id, "serpent_hide"),
    berserk: statusStrength(world, id, "berserk") + effectStrength(world, id, "rampage"),
    primal_roar: effectStrength(world, id, "primal_roar"),
    // Corpse-eat timed buffs
    cunning_reflex: statusStrength(world, id, "cunning_reflex"),
    keen_eye: statusStrength(world, id, "keen_eye"),
    spider_sense: statusStrength(world, id, "spider_sense"),
    thermal_sense: statusStrength(world, id, "thermal_sense"),
    blood_rage: statusStrength(world, id, "blood_rage"),
    war_fed: statusStrength(world, id, "war_fed"),
    invisible: capabilityStrength(world, id, "concealed"),
    phase_shift: capabilityStrength(world, id, "phase_shift"),
    ogre_bulk: statusStrength(world, id, "ogre_bulk"),
    shadow_cloak: statusStrength(world, id, "shadow_cloak") + (shadowVeilAmbushReady(world, id) ? 1 : 0),
    dark_sight: statusStrength(world, id, "dark_sight"),
    battle_fury: statusStrength(world, id, "battle_fury") + (effectStrength(world, id, "quicken") > 0 ? 1 : 0),
    fey_grace: statusStrength(world, id, "fey_grace"),
    blinded: statusStrength(world, id, "blinded"),
    staggered: statusStrength(world, id, "staggered"),
    frozen: capabilityStrength(world, id, "frozen"),
  };

  const posture = world.get(id, CombatPosture);
  const stance = posture?.stance === COMBAT_POSTURES.aggressive
    ? COMBAT_POSTURES.aggressive
    : (posture?.stance === COMBAT_POSTURES.guarded ? COMBAT_POSTURES.guarded : COMBAT_POSTURES.balanced);

  /** @type {Array<{stat:'attack'|'defense', source:string, value:number, reason:string}>} */
  const modifiers = [];

  let attackBonus = 1 + accuracy;
  pushModifier(modifiers, "attack", "base", 1, "base-to-hit");
  pushModifier(modifiers, "attack", "resolved:accuracy", accuracy, "resolved-accuracy");
  if (felineRodentBonus) {
    pushModifier(modifiers, "attack", "trait:feline", 2, "rodent-hunter-to-hit");
    attackBonus += 2;
  }

  if (rules.includeAttackStatuses) {
    pushModifier(modifiers, "attack", "status:disease", -statusTotals.disease, "disease-penalty");
    pushModifier(modifiers, "attack", "status:hunger", -statusTotals.hunger, "hunger-penalty");
    pushModifier(modifiers, "attack", "status:weakened", -statusTotals.weakened, "weakened-penalty");
    pushModifier(modifiers, "attack", "status:cursed", -statusTotals.cursed, "cursed-penalty");
    pushModifier(modifiers, "attack", "status:blessed", statusTotals.blessed, "blessed-bonus");
    pushModifier(modifiers, "attack", "status:berserk", statusTotals.berserk > 0 ? 3 : 0, "berserk-bonus");
    pushModifier(modifiers, "attack", "status:primal_roar", statusTotals.primal_roar * 5, "primal-roar-bonus");
    pushModifier(modifiers, "attack", "status:keen_eye", statusTotals.keen_eye * 2, "keen-eye-bonus");
    pushModifier(modifiers, "attack", "status:thermal_sense", statusTotals.thermal_sense * 2, "thermal-sense-bonus");
    pushModifier(modifiers, "attack", "status:blood_rage", statusTotals.blood_rage * 3, "blood-rage-bonus");
    pushModifier(modifiers, "attack", "status:war_fed", statusTotals.war_fed * 2, "war-fed-bonus");
    pushModifier(modifiers, "attack", "status:dark_sight", statusTotals.dark_sight * 2, "dark-sight-bonus");
    pushModifier(modifiers, "attack", "status:battle_fury", statusTotals.battle_fury * 2, "battle-fury-bonus");
    pushModifier(modifiers, "attack", "status:staggered", -statusTotals.staggered, "staggered-penalty");

    const blindedAtkPenalty = getBlindedAttackPenalty(statusTotals.blinded);
    pushModifier(modifiers, "attack", "status:blinded", -blindedAtkPenalty, "blinded-attack-penalty");

    attackBonus += (
      -statusTotals.disease
      -statusTotals.hunger
      -statusTotals.weakened
      -statusTotals.cursed
      +statusTotals.blessed
      +(statusTotals.berserk > 0 ? 3 : 0)
      +(statusTotals.primal_roar * 5)
      +(statusTotals.keen_eye * 2)
      +(statusTotals.thermal_sense * 2)
      +(statusTotals.blood_rage * 3)
      +(statusTotals.war_fed * 2)
      +(statusTotals.dark_sight * 2)
      +(statusTotals.battle_fury * 2)
      -statusTotals.staggered
      -blindedAtkPenalty
    );
  }

  for (const [_modifierId, modifier] of descendantsWith(world, id, AuraStatModifier)) {
    if (modifier?.stat !== "attack") continue;
    pushModifier(modifiers, "attack", `aura:${modifier.key || modifier.sourceId}`, Number(modifier.amount || 0), "aura-bonus");
    attackBonus += Number(modifier.amount || 0);
  }

  if (stance === COMBAT_POSTURES.aggressive) {
    pushModifier(modifiers, "attack", "posture:aggressive", 2, "aggressive-bonus");
    attackBonus += 2;
  } else if (stance === COMBAT_POSTURES.guarded) {
    pushModifier(modifiers, "attack", "posture:guarded", -1, "guarded-penalty");
    attackBonus -= 1;
  }

  if (rules.clampAttackAtZero && attackBonus < 0) {
    pushModifier(modifiers, "attack", "rule:attackFloor", -attackBonus, "min-zero");
    attackBonus = 0;
  }

  let defenseContribution = evade;
  pushModifier(modifiers, "defense", "base", 10, "base-armor-class");
  pushModifier(modifiers, "defense", "resolved:evade", evade, "resolved-evade");

  if (rules.includeDefenseStatuses) {
    pushModifier(modifiers, "defense", "status:disease", -statusTotals.disease, "disease-penalty");
    pushModifier(modifiers, "defense", "status:hunger", -statusTotals.hunger, "hunger-penalty");
    pushModifier(modifiers, "defense", "status:weakened", -statusTotals.weakened, "weakened-penalty");
    pushModifier(modifiers, "defense", "status:cursed", -statusTotals.cursed, "cursed-penalty");
    pushModifier(modifiers, "defense", "status:blessed", statusTotals.blessed, "blessed-bonus");

    pushModifier(modifiers, "defense", "status:cunning_reflex", statusTotals.cunning_reflex * 2, "cunning-reflex-bonus");
    pushModifier(modifiers, "defense", "status:phase_shift", statusTotals.phase_shift * 4, "phase-shift-bonus");
    pushModifier(modifiers, "defense", "status:fey_grace", statusTotals.fey_grace * 3, "fey-grace-bonus");
    pushModifier(modifiers, "defense", "status:spider_sense", statusTotals.spider_sense * 2, "spider-sense-bonus");
    pushModifier(modifiers, "defense", "status:staggered", -(statusTotals.staggered * 2), "staggered-penalty");

    defenseContribution += (
      -statusTotals.disease
      -statusTotals.hunger
      -statusTotals.weakened
      -statusTotals.cursed
      +statusTotals.blessed
      +(statusTotals.cunning_reflex * 2)
      +(statusTotals.phase_shift * 4)
      +(statusTotals.fey_grace * 3)
      +(statusTotals.spider_sense * 2)
      -(statusTotals.staggered * 2)
    );
  }

import {
  appendCharacterMenuTabs, markScrollable,
  decorateButton, humanize, sanitize, bracketize,
  show, hide, hideItemTooltip, rarityStyle, renderItemDetails,
  CHARACTER_SLOT_ORDER, installDetachableKeyHandler, pulseRow,
  UI, dispatchCharacterMenuTabCycle,
} from './overlayUtils.js';
import { applyAtlasIcon, ITEM_ICON_ATLAS, SPELL_ICON_ATLAS } from './atlasIcons.js';

/**
 * Resolve the primary equipment-row artwork without exposing unidentified gear.
 * @param {any} item
 * @param {string} slot
 * @returns {{ atlas: any, id: string, fallback: string, size: number }}
 */
export function resolveEquipmentIcon(item, slot) {
  const type = String(item?.type || '').toLowerCase();
  const isSpell = slot === 'brain' || type === 'spell';
  if (isSpell) {
    const id = String(item?.iconId || item?.spellId || item?.id || '').replace(/^spell:/, '');
    return { atlas: SPELL_ICON_ATLAS, id, fallback: String(item?.symbol || item?.glyph || '✦'), size: 30 };
  }

  const safeFallback = {
    potion: '◈', scroll: '▤', wand: '⚡', gem: '◇', ammo: '➶', food: '♨',
  }[type] || (item?.slot ? '◆' : '◇');
  const identified = item?.identified !== false;
  return {
    atlas: ITEM_ICON_ATLAS,
    id: identified ? String(item?.iconId || item?.identity || '') : '',
    fallback: identified ? String(item?.glyph || safeFallback) : safeFallback,
    size: 30,
  };
}

/**
 * @param {HTMLDivElement & {_inner?:HTMLDivElement}} panel
 * @param {{ playerName?: string, stats?: Record<string, any>, activeEffects?: Array<any>, equippedBySlot?: Record<string, any> }} data
 */
export function renderCharacterSheet(panel, data) {
  const SEASON_COLORS = {
    spring: '#7ec87a',
    summer: '#f0c95a',
    autumn: '#d4834a',
    winter: '#8ab4d6',
  };
  const existingDetach = /** @type {any} */ (panel)._characterSheetDetach;
  if (typeof existingDetach === 'function') {
    try { existingDetach(); } catch (e) { console.debug('[overlay] character sheet detach failed:', e); }
  }

  const el = /** @type {HTMLDivElement} */ (/** @type {any} */ (panel)._inner);
  el.innerHTML = '';
  el.style.overflowX = 'hidden';
  el.style.width = 'min(760px, 92vw)';
  appendCharacterMenuTabs(el, 'character');

  const playerName = String(data?.playerName || 'Hero').trim() || 'Hero';
  const stats = data?.stats && typeof data.stats === 'object' ? data.stats : {};
  const equippedBySlot = data?.equippedBySlot && typeof data.equippedBySlot === 'object'
    ? data.equippedBySlot
    : {};
  const gearMechanics = [];
  const seenGearMechanics = new Set();
  for (const slot of CHARACTER_SLOT_ORDER) {
    const item = equippedBySlot?.[slot]?.item;
    const mechanics = Array.isArray(item?.mechanics) ? item.mechanics : [];
    for (const mechanic of mechanics) {
      const context = String(mechanic?.context || '').trim();
      const text = String(mechanic?.text || '').trim();
      if (!text || (context !== 'Equip' && context !== 'Enchant')) continue;
      const label = `${context} ${text}`;
      if (seenGearMechanics.has(label)) continue;
      seenGearMechanics.add(label);
      gearMechanics.push(label);
    }
  }
  const traits = Array.isArray(data?.traits) ? data.traits : [];
  const calendar = data?.calendar && typeof data.calendar === 'object' ? data.calendar : null;

  const title = document.createElement('div');
  title.textContent = `${playerName} \u00b7 Character Sheet`;
  title.style.fontWeight = 'bold';
  title.style.marginBottom = '8px';
  el.appendChild(title);

  if (calendar?.formatted) {
    const calendarCard = document.createElement('div');
    Object.assign(calendarCard.style, {
      marginBottom: '10px',
      padding: '8px 10px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      fontSize: '13px',
      lineHeight: '1.4',
      color: SEASON_COLORS[String(calendar?.season || '')] || UI.TEXT,
      wordBreak: 'break-word',
    });
    const moonEmoji = String(calendar?.moonEmoji || '');
    const moonLabel = String(calendar?.moonLabel || '');
    calendarCard.textContent = `${moonEmoji ? `${moonEmoji} ` : ''}${String(calendar.formatted)}${moonLabel ? ` \u00b7 ${moonLabel}` : ''}`;
    el.appendChild(calendarCard);
  }

  const statCard = document.createElement('div');
  Object.assign(statCard.style, {
    padding: '8px',
    border: UI.BORDER,
    borderRadius: UI.RADIUS,
    background: UI.DEFAULT_BG,
    display: 'grid',
    gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
    gap: '6px 12px',
    fontSize: '13px',
  });
  el.appendChild(statCard);

  function deltaColor(value, baseline = 0) {
    const n = Number(value || 0);
    if (n > baseline) return '#64c87a';
    if (n < baseline) return '#e06a6a';
    return null;
  }

  // [label, value, color|null]  — null = default text color
  const statRows = [
    ['Strength', `${Number(stats.strength || 0)}`, deltaColor(stats.strength)],
    ['Dexterity', `${Number(stats.dexterity || 0)}`, deltaColor(stats.dexterity)],
    ['Intelligence', `${Number(stats.intelligence || 0)}`, deltaColor(stats.intelligence)],
    ['Vitality', `${Number(stats.vitalityStat || 0)}`, deltaColor(stats.vitalityStat)],
    ['HP', `${Number(stats.hp || 0)}/${Number(stats.maxHp || 0)}`],
    ['Mana', `${Number(stats.mana || 0)}/${Number(stats.maxMana || 0)}`],
    ['Stamina', `${Number(stats.stamina || 0)}/${Number(stats.maxStamina || 0)}`],
    ['Attack', `${Number(stats.attack || 0)}`, deltaColor(stats.attack)],
    ['Defense', `${Number(stats.defense || 0)}`, deltaColor(stats.defense)],
    ['Accuracy', `${Number(stats.accuracy || 0)}`, deltaColor(stats.accuracy)],
    ['Damage Power', `${Number(stats.damagePower || 0)}`, deltaColor(stats.damagePower)],
    ['Evade', `${Number(stats.evade || 0)}`, deltaColor(stats.evade)],
    ['Mitigation', `${Number(stats.mitigation || 0)}`, deltaColor(stats.mitigation)],
    ['Spell Power', `${Number(stats.spellPower || 0)}`, deltaColor(stats.spellPower)],
    ['Armor Class', `${Number(stats.armorClass || 0)}`, deltaColor(stats.armorClass, 10)],
    ['Luck', `${Number(stats.luck || 0)}`, deltaColor(stats.luck)],
    ['Crit %', `${Number(stats.critChancePercent || 0).toFixed(1)}`, deltaColor(stats.critChancePercent)],
    ['Crit Mult', `\u00d7${(2 + Number(stats.critMult || 0)).toFixed(1)}`, deltaColor(stats.critMult)],
    ['Dmg Bonus', `${Number(stats.damageFlatBonus || 0)}`, deltaColor(stats.damageFlatBonus)],
    ['Mana Regen', `${Number(stats.manaRegen || 0).toFixed(2)}/t`, deltaColor(stats.manaRegenDerived)],
    ['Stam Regen', `${Number(stats.staminaRegen || 0).toFixed(1)}/t`, deltaColor(stats.staminaRegenDerived)],
    ['Carry', `${Number(stats.carryWeight || 0).toFixed(1)}/${Number(stats.carryLimit || 0).toFixed(1)} kg · ${humanize(String(stats.carryState || 'unburdened'))}`],
    ['Max HP Bonus', `${Number(stats.maxHpDerived || 0)}`, deltaColor(stats.maxHpDerived)],
    ['Speed', `${Number(stats.speed || 1)}`, deltaColor(stats.speed, 1) === '#64c87a' ? '#e06a6a' : deltaColor(stats.speed, 1) === '#e06a6a' ? '#64c87a' : null],
    ['Gold', `${Number(stats.gold || 0)}`],
    ['Hunger', `${humanize(String(stats.hungerLevel || 'normal'))} (${Number(stats.hunger || 0)})`],
    ['Depth', `${Number(stats.depth || 0)}`],
    ['Turn', `${Number(stats.turn || 0)}`],
  ];
  for (const [label, value, color] of statRows) {
    const row = document.createElement('div');
    const lbl = document.createElement('span');
    lbl.textContent = `${label}: `;
    const val = document.createElement('span');
    val.textContent = value;
    if (color) val.style.color = color;
    row.appendChild(lbl);
    row.appendChild(val);
    statCard.appendChild(row);
  }

  // Resistances — only show non-zero entries
  const resistRows = [
    ['Kinetic DR', Number(stats.kineticDR || 0)],
    ['Fire Resist', Number(stats.fireResist || 0)],
    ['Cold Resist', Number(stats.coldResist || 0)],
    ['Poison Resist', Number(stats.poisonResist || 0)],
    ['Acid Resist', Number(stats.acidResist || 0)],
    ['Rad Resist', Number(stats.radiationResist || 0)],
    ['Elec Resist', Number(stats.electricResist || 0)],
    ['Blunt Resist', Number(stats.bluntResist || 0)],
    ['Slash Resist', Number(stats.slashResist || 0)],
    ['Pierce Resist', Number(stats.pierceResist || 0)],
  ].filter(([, v]) => v !== 0);

  if (resistRows.length) {
    const resistHeader = document.createElement('div');
    resistHeader.textContent = 'Resistances';
    resistHeader.style.marginTop = '10px';
    resistHeader.style.fontWeight = 'bold';
    el.appendChild(resistHeader);

    const resistCard = document.createElement('div');
    Object.assign(resistCard.style, {
      marginTop: '6px',
      padding: '8px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      display: 'grid',
      gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
      gap: '6px 12px',
      fontSize: '13px',
    });
    for (const [label, v] of resistRows) {
      const row = document.createElement('div');
      const lbl = document.createElement('span');
      lbl.textContent = `${label}: `;
      const val = document.createElement('span');
      val.textContent = `${v}`;
      val.style.color = deltaColor(v) || UI.TEXT;
      row.appendChild(lbl);
      row.appendChild(val);
      resistCard.appendChild(row);
    }
    el.appendChild(resistCard);
  }

  if (traits.length > 0) {
    const traitsTitle = document.createElement('div');
    traitsTitle.textContent = 'Traits';
    traitsTitle.style.marginTop = '10px';
    traitsTitle.style.fontWeight = 'bold';
    el.appendChild(traitsTitle);

    const traitsCard = document.createElement('div');
    Object.assign(traitsCard.style, {
      marginTop: '6px',
      padding: '8px',
      border: UI.BORDER,
      borderRadius: UI.RADIUS,
      background: UI.DEFAULT_BG,
      fontSize: '13px',
    });
    for (const t of traits) {
      const row = document.createElement('div');
      row.style.marginBottom = '4px';
      const lbl = document.createElement('span');
      lbl.textContent = String(t.label || t.key || '');
      lbl.style.color = '#ffd966';
      lbl.style.fontWeight = 'bold';
      const desc = document.createElement('span');
      desc.textContent = ` \u2014 ${String(t.description || '')}`;
      for (const [abilityId, spec] of Object.entries(def._contentAbilities)) {
        const cd = getItemCooldown(world, itemId);
        results.push({
          kind: 'item-use',
          id: `item-use:${identity}:${abilityId}:${itemId}`,
          itemId,
          identity,
          abilityId,
          name: spec.name || abilityId,
          symbol: spec.icon || '?',
          iconAtlas: 'items',
          iconId: identity,
          cost: spec.cost || 0,
          costKind: spec.costKind || 'item',
          cdRemaining: cd ? Math.max(0, Number(cd.remaining || 0) | 0) : 0,
          cdMax: cd ? Math.max(0, Number(cd.max || 0) | 0) : (spec.cooldown || 0),
          auto: true,
        });
      }
    }
    return results;
  }

  function updateVitalsHUD() {
    const pe = playerEntity(world);
    if (!pe) return;
    /** @type {{ hp?:number, maxHp?:number }|null} */
    const vit = /** @type any */ (world.get(pe.id, Vitality));
    const mana = getPlayerMana();
    const stam = /** @type any */ (world.get(pe.id, Stamina));
    const passive = getPassiveBonuses(world, pe.id);

    const rawHp = Number(vit?.hp ?? 0);
    const maxHp = vit ? effectiveMaxHp(world, pe.id, vit) : 0;
    const fxT = typeof getFxTime === 'function' ? getFxTime() : 0;
    const hp = impactTracker.visualHp(pe.id, rawHp, maxHp, fxT);
    const stamina = Number(stam?.stamina ?? 0);
    const maxStaminaBonus = Number(passive?.maxStaminaDerived ?? 0);
    const maxStamina = Number(stam?.maxStamina ?? 100) + maxStaminaBonus;
    const encumbrance = resolveEncumbrance(getCarriedWeight(world, pe.id), getCarryCapacity(world, pe.id));
    const encumbered = snapshotStatusState(world, pe.id)?.allStatuses
      ?.some((status) => status.type === "encumbered") === true;
    if (hp !== lastVitals.hp || maxHp !== lastVitals.maxHp ||
        mana.mana !== lastVitals.mana || mana.maxMana !== lastVitals.maxMana ||
        stamina !== lastVitals.stamina || maxStamina !== lastVitals.maxStamina ||
        encumbrance.loadRatio !== lastVitals.encumbrance || encumbered !== lastVitals.encumbered) {
      lastVitals = { hp, maxHp, mana: mana.mana, maxMana: mana.maxMana, stamina, maxStamina, encumbrance: encumbrance.loadRatio, encumbered };
      try {
        window.dispatchEvent(new CustomEvent("ui:updateVitals", { detail: { ...lastVitals, encumbrance: { ...encumbrance, encumbered } } }));
      } catch (e) { console.debug('[hudFeeds] dispatch ui:updateVitals:', e); }
    }
  }

  /**
   * Average roll for a dice spec like "2d6" → 7.
   * @param {string} spec
   * @returns {number}
   */
  function averageDice(spec) {
    const m = /^\s*(\d+)d(\d+)\s*$/i.exec(String(spec || ""));
    if (!m) return 1;
    const count = Math.max(1, parseInt(m[1], 10) | 0);
    const sides = Math.max(2, parseInt(m[2], 10) | 0);
    return count * (sides + 1) / 2;
  }

  function updateCombatHUD() {
    const pe = playerEntity(world);
    if (!pe) return;
    const eq = /** @type any */ (world.get(pe.id, Equipment));
    const passive = getPassiveBonuses(world, pe.id);
    const canonical = resolveCanonicalStats(world, pe.id);
    const wid = Number(eq?.weapon || 0);
    const rangedId = Number(eq?.ranged || 0);
    const combat = resolveCombatSnapshot(world, pe.id, { mode: "melee" });

    // Compute actual expected damage: avg dice + flat bonus, scaled by mult
    const wInfo = wid ? world.get(wid, ItemInfo) : null;
    const dmgDice = wInfo?.damageDice ? String(wInfo.damageDice) : (wid ? "1d2" : "1d2");
    const avgRoll = averageDice(dmgDice);
    const flatBonus = Number(combat?.damageFlatBonus ?? 0);
    const damageMult = Number(combat?.damageMult ?? 1);
    const atk = Math.max(0, Math.floor((avgRoll + flatBonus) * damageMult));

    const luck = Number(combat?.luck ?? canonical?.luck ?? 0);
    const evade = Number(canonical?.evade ?? 0);
    const armorClass = Number(combat?.armorClass ?? (10 + evade));
    const defenseContribution = Math.max(0, Math.round(armorClass - 10));
    // DEF% is an at-a-glance composite: physical reduction plus to-hit defense.
    const CANONICAL_HIT = 100;
    const afterBlunt = resolveResistance(world, pe.id, CANONICAL_HIT, 'blunt');
    const afterSlash = resolveResistance(world, pe.id, CANONICAL_HIT, 'slash');
    const afterPierce = resolveResistance(world, pe.id, CANONICAL_HIT, 'pierce');
    const physicalReduction = Math.round(CANONICAL_HIT - (afterBlunt + afterSlash + afterPierce) / 3);
    const def = Math.max(0, physicalReduction + defenseContribution);
    const critPct = (Number(combat?.critChance ?? canonical?.critChancePhysical ?? 0) * 100) + luck;
    const posture = String(combat?.posture?.stance || "balanced");
    const mitigation = Number(canonical?.mitigation ?? 0);
    const rangedInfo = rangedId ? world.get(rangedId, ItemInfo) : null;
    const rangedCount = Number(rangedInfo?.count || 0);
    const wName = wid ? (world.get(wid, NamedIdentity)?.name || wInfo?.description || wInfo?.type) : "";
    const rangedName = rangedId ? (world.get(rangedId, NamedIdentity)?.name || rangedInfo?.description || rangedInfo?.type) : "";
    const wCoating = wInfo?.coating && typeof wInfo.coating === 'object' ? wInfo.coating : null;
    const coatingSig = wCoating ? `${wCoating.kind}:${wCoating.charges || 0}` : "";
    const rangedType = String(rangedInfo?.type || "");
    /** @type {Map<string, { key: string, turns: number, stacks: number }>} */
    const statusMap = new Map();
    const effectRows = buildEffectRows(world, pe.id);
    for (const row of effectRows) statusMap.set(row.instanceId || row.key, row);
    const hc = /** @type any */ (world.get(pe.id, Hunger));
    if (hc) {
      const level = hc.satiation > 0 ? "satiated" : getHungerLevel(Number(hc.hunger || 0));
      if (level !== "normal") {
        const key = String(level).toLowerCase();
        const turns = hc.satiation > 0 ? Math.max(0, Number(hc.satiation || 0)) : 9999;
        const stacks = 1;
        const prev = statusMap.get(key);
