import { Stamina } from '../components/Stamina.js';
import { getPassiveBonuses } from '../utils/passiveBonuses.js';
import { getResolvedStats } from '../utils/derivedStats.js';
import { Encumbrance } from '../components/Encumbrance.js';
import {
  HEAVY_STAMINA_REGEN_MULTIPLIER,
  OVERLOADED_STAMINA_REGEN_MULTIPLIER,
} from '../data/encumbranceTuning.js';

/**
 * Regenerate stamina each turn based on base rate plus equipment bonuses.
 * Caps at effective max stamina (base + equipment bonuses).
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function staminaRegenerationSystem(world) {
  for (const [entity, staminaComp] of world.query(Stamina)) {
    if (!staminaComp) continue;

    // Cooldown: skip regen on turns where stamina was spent.
    // Direct mutation — world.set() defers during ticks and would
    // spread stale values, clobbering combat/dig deductions.
    const cd = Number(staminaComp.regenCooldown ?? 0);
    if (cd > 0) {
      staminaComp.regenCooldown = cd - 1;
      continue;
    }

    const passive = getPassiveBonuses(world, entity);
    const maxStaminaBonus = Number(passive?.maxStaminaDerived ?? 0);
    const effectiveMaxStamina = staminaComp.maxStamina + maxStaminaBonus;

    if (staminaComp.stamina >= effectiveMaxStamina) continue;

    const baseRate = Number(staminaComp.staminaRegen ?? 0);
    const regenBonus = Number(passive?.staminaRegenDerived ?? 0);
    const derivedRegenMod = Number(getResolvedStats(world, entity)?.staminaRegen ?? 0);
    const encumbrance = world.get(entity, Encumbrance);
    const loadMultiplier = encumbrance?.overloaded
      ? OVERLOADED_STAMINA_REGEN_MULTIPLIER
      : encumbrance?.heavilyLoaded
      ? HEAVY_STAMINA_REGEN_MULTIPLIER
      : 1;
    const rate = Math.max(0, baseRate + regenBonus + derivedRegenMod) * loadMultiplier;

    staminaComp.stamina = Math.min(effectiveMaxStamina, staminaComp.stamina + rate);
  }
}
# Technical Memo: Stat Resolution Pipeline Follow-Up

## Finding

Current combat logic still includes content-specific checks (for example, `stoneskin` by name) inside mechanics systems:

- `src/rules/systems/combatSystem.js`
- `src/rules/systems/rangedAttackSystem.js`

This works for now, but it conflicts with the architecture direction where mechanics should stay content-agnostic.

## Why This Matters

- Logic is duplicated across melee and ranged paths.
- Modifier precedence/stacking is implicit instead of explicit.
- New effects increase regression risk when each path is patched separately.
- Replay/audit/debug transparency is reduced.

## Recommended Shift

Introduce a deterministic stat resolution pipeline and make hit-resolution systems consume resolved snapshots only.

## Proposed Contract

`resolveCombatSnapshot(world, entityId, context)` returns normalized derived stats:

- `attackBonus`
- `defenseClass`
- `damage`/channels
- `resistances`
- ordered `modifiers[]` (source + reason)

Requirements:

- deterministic source ordering
- stable stacking/precedence rules
- optional audit breadcrumbs for explainability

## Architecture Alignment

- Payload hooks remain on content data defs/registries.
- ECS components remain pure data (no function values).
- Combat mechanics consume pipeline output rather than checking specific status names.

## Migration Plan

1. Extract current `stoneskin` AC behavior into resolver with parity.
2. Switch both melee and ranged systems to resolver output.
3. Add tests for parity, precedence, stacking, and determinism.
4. Remove inline status-name checks from combat systems.

## Definition of Done

- No direct status-name checks in combat systems.
- Shared resolver used by all hit-resolution paths.
- Deterministic tests pass with same seed + same inputs.
- Modifier application is auditable and transparent.
# Damage Pipeline Technical Memo

## Date
February 16, 2026

## Purpose
Document the damage-pipeline consolidation, current guarantees, validation status, and remaining work.

## Background
Damage application had drifted into many one-off `Vitality.hp` mutations across systems and scripts. That caused:

- Inconsistent invulnerability handling
- Inconsistent event emission (`damage` vs `damaged`)
- Ad-hoc death emission behavior
- Difficult-to-audit gameplay regressions

The codebase now converges on a single canonical damage path.

## Canonical Rule
All HP reduction in rules code must route through:

- `src/rules/utils/dealDamage.js`

Direct HP subtraction in rules code is prohibited outside that utility.

## Pipeline Contract
`dealDamage(world, spec)` now owns:

1. Target and amount validation
2. Invulnerability gate (`isEntityInvulnerable`)
3. Resistance resolution by damage type
4. HP subtraction
5. Unified `'damaged'` event emission
6. Unified `'died'` emission on lethal damage
7. Structured return result (`applied`, `killed`, `amount`, `reason`, etc.)

## Event Standardization
Damage event semantics are now:

- Use `'damaged'` (not `'damage'`)
- Use `'died'` only from `dealDamage`

This keeps listeners deterministic and removes split event contracts.

## Key Fixes Completed

### 1) Monster `onDamaged` hooks
- `affixTriggerSystem` now executes monster `onDamaged` callback arrays through `CombatCallbackContext` + `runCallbackList`.
- Integration tests verify real combat path behavior (including demon hellfire retaliation and skeleton reassemble) via:
  - `tests/monsterOnDamagedIntegration.test.mjs`

### 2) Tombstone killer attribution
- Tombstone listener now records killer attribution even when `cause` is present.
- Edge case (mutual-kill retaliation cascade) is covered:
  - `tests/tombstoneKillerAttribution.test.mjs`

### 3) Pipeline unit coverage
- New tests validate `dealDamage` behavior:
  - invulnerability
  - resistance resolution
  - bypass flags
  - event payloads
  - death emission
- File:
  - `tests/dealDamage.test.mjs`

## Audit Snapshot
Current audit confirms:

- HP subtraction is centralized to `src/rules/utils/dealDamage.js`.
- No legacy `world.on/emit('damage', ...)` usage remains in `src/`.
- `'died'` emission is centralized to `dealDamage`.

## Known Limitation (Intentional/Outstanding)
Equipment/affix-driven elemental resistances are not yet fully wired as an equip-time stat pipeline.

Implication:
- A hypothetical "Ring of Fire Resistance" will only work if it writes to `Resistances.thermal.burnMult` (or equivalent) through explicit rules logic.
- Current equipment derived stats focus on combat/economy modifiers and do not automatically project full resistance fields.

## Engineering Policy Going Forward

1. New damage features must call `dealDamage`.
2. No new direct HP subtraction callsites.
3. New listeners should consume `'damaged'`/`'died'` contracts only.
4. Any exception (`bypassInvuln`, `bypassResist`, `noTrigger`) must be explicit at callsite with gameplay rationale.

## Recommended Next Step
Implement resistance projection from equipped items/affixes into the `Resistances` component so itemized elemental defense (e.g., fire resist rings) works as first-class gameplay, not ad-hoc script logic.

