  1	import { getPassiveBonuses } from "./passiveBonuses.js";
  2	import { resolveDerivedStats } from "./derivedStats.js";
  3	
  4	/**
  5	 * Merge all stat inputs into a canonical stat view for combat/damage consumers.
  6	 * Derived-expression stats are authoritative semantic channels; passive/equipment
  7	 * bonuses are treated as additional input sources to those channels.
  8	 *
  9	 * @param {import('../../lib/ecs-js/index.js').World} world
 10	 * @param {number} entityId
 11	 */
 12	export function resolveCanonicalStats(world, entityId) {
 13	  const id = Number(entityId || 0) | 0;
 14	  const resolved = resolveDerivedStats(world, id);
 15	  const passive = getPassiveBonuses(world, id);
 16	
 17	  const baseDexterity = Number(resolved?.dexterity || 0);
 18	  const dexterityDerived = Number(passive?.dexterityDerived || 0);
 19	  const totalDexterity = baseDexterity + dexterityDerived;
 20	  const baseDexBonus = Math.floor(Math.max(0, baseDexterity - 10) / 2);
 21	  const totalDexBonus = Math.floor(Math.max(0, totalDexterity - 10) / 2);
 22	  const dexBonusDelta = totalDexBonus - baseDexBonus;
 23	
 24	  const accuracyDerived = Number(passive?.accuracyDerived || 0);
 25	  const damagePowerDerived = Number(passive?.damagePowerDerived || 0);
 26	  const physicalPenetrationDerived = Number(passive?.physicalPenetrationDerived || 0);
 27	  const bluntPenetrationDerived = Number(passive?.bluntPenetrationDerived || 0);
 28	  const slashPenetrationDerived = Number(passive?.slashPenetrationDerived || 0);
 29	  const piercePenetrationDerived = Number(passive?.piercePenetrationDerived || 0);
 30	  const evadeDerived = Number(passive?.evadeDerived || 0);
 31	  const mitigationDerived = Number(passive?.mitigationDerived || 0);
 32	  const critChanceDerived = Number(passive?.critChanceDerived || 0);
 33	  const critMultDerived = Number(passive?.critMultDerived || 0);
 34	
 35	  return Object.freeze({
 36	    ...resolved,
 37	    dexterity: totalDexterity,
 38	    accuracy: Number(resolved?.accuracy || 0) + accuracyDerived + dexBonusDelta,
 39	    damagePower: Number(resolved?.damagePower || 0) + damagePowerDerived,
 40	    physicalPenetration: Number(resolved?.physicalPenetration || 0) + physicalPenetrationDerived,
 41	    bluntPenetration: Number(resolved?.bluntPenetration || 0) + bluntPenetrationDerived,
 42	    slashPenetration: Number(resolved?.slashPenetration || 0) + slashPenetrationDerived,
 43	    piercePenetration: Number(resolved?.piercePenetration || 0) + piercePenetrationDerived,
 44	    evade: Number(resolved?.evade || 0) + evadeDerived + dexBonusDelta,
 45	    mitigation: Number(resolved?.mitigation || 0) + mitigationDerived,
 46	    critChancePhysical: Number(resolved?.critChancePhysical || 0) + critChanceDerived + (dexBonusDelta * 0.01),
 47	    critChanceSpell: Number(resolved?.critChanceSpell || 0) + critChanceDerived,
